from collections import defaultdict

class Solution:
    def getDistances(self, arr: list[int]) -> list[int]:
        n = len(arr)
        groups = defaultdict(list)
        for i, val in enumerate(arr):
            groups[val].append(i)

        ans = [0] * n

        for val, indices in groups.items():
            m = len(indices)
            pref = [0] * (m + 1)
            for i in range(m):
                pref[i + 1] = pref[i] + indices[i]

            total_sum = pref[m]
            for i in range(m):
                idx = indices[i]
                left_contrib = i * idx - pref[i]
                right_contrib = (total_sum - pref[i + 1]) - (m - 1 - i) * idx
                ans[idx] = left_contrib + right_contrib

        return ans

#include <vector>
#include <unordered_map>

class Solution {
public:
    std::vector<long long> getDistances(std::vector<int>& arr) {
        int n = arr.size();
        std::unordered_map<int, std::vector<int>> groups;
        for (int i = 0; i < n; ++i) {
            groups[arr[i]].push_back(i);
        }

        std::vector<long long> ans(n, 0);

        for (const auto& [val, indices] : groups) {
            int m = indices.size();
            std::vector<long long> pref(m + 1, 0);
            for (int i = 0; i < m; ++i) {
                pref[i + 1] = pref[i] + indices[i];
            }

            long long totalSum = pref[m];
            for (int i = 0; i < m; ++i) {
                long long idx = indices[i];
                long long leftContrib = 1LL * i * idx - pref[i];
                long long rightContrib = (totalSum - pref[i + 1]) - 1LL * (m - 1 - i) * idx;
                ans[idx] = leftContrib + rightContrib;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public long[] getDistances(int[] arr) {
        int n = arr.length;
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int i = 0; i < n; i++) {
            groups.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }

        long[] ans = new long[n];

        for (List<Integer> indices : groups.values()) {
            int m = indices.size();
            long[] pref = new long[m + 1];
            for (int i = 0; i < m; i++) {
                pref[i + 1] = pref[i] + indices.get(i);
            }

            long totalSum = pref[m];
            for (int i = 0; i < m; i++) {
                long idx = indices.get(i);
                long leftContrib = (long) i * idx - pref[i];
                long rightContrib = (totalSum - pref[i + 1]) - (long) (m - 1 - i) * idx;
                ans[(int) idx] = leftContrib + rightContrib;
            }
        }
        return ans;
    }
}

