var getDistances = function(arr) {
    const n = arr.length;
    const groups = new Map();
    for (let i = 0; i < n; i++) {
        if (!groups.has(arr[i])) groups.set(arr[i], []);
        groups.get(arr[i]).push(i);
    }

    const ans = new Array(n).fill(0);

    for (const indices of groups.values()) {
        const m = indices.length;
        const pref = new Array(m + 1).fill(0);
        for (let i = 0; i < m; i++) {
            pref[i + 1] = pref[i] + indices[i];
        }

        const totalSum = pref[m];
        for (let i = 0; i < m; i++) {
            const idx = indices[i];
            const leftContrib = i * idx - pref[i];
            const rightContrib = (totalSum - pref[i + 1]) - (m - 1 - i) * idx;
            ans[idx] = leftContrib + rightContrib;
        }
    }
    return ans;
};
